    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Coe 6000 lbs Powered with Coil Car$str$, 1.73, 4.07, 1.08, $str$Uncoiler:Coe 6000 lbs Powered with Coil Car:India$str$),
    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Coe 8000 lbs Powered$str$, 1.73, 3.04, 0.96, $str$Uncoiler:Coe 8000 lbs Powered:India$str$),
    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Coe 8000 lbs Powered with Coil Car$str$, 1.73, 5.04, 1.11, $str$Uncoiler:Coe 8000 lbs Powered with Coil Car:India$str$),
    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Cooper Weymouth 2500 18DP Powered Double Mandrel$str$, 1.73, 2.67, 0.94, $str$Uncoiler:Cooper Weymouth 2500 18DP Powered Double Mandrel:India$str$),
    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Uncoiler 10000 lbs Powered with Coil Car$str$, 1.73, 9.08, 1.31, $str$Uncoiler:Uncoiler 10000 lbs Powered with Coil Car:India$str$),
    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Uncoiler 20000 lbs Powered Double Mandrel$str$, 1.73, 15.85, 1.21, $str$Uncoiler:Uncoiler 20000 lbs Powered Double Mandrel:India$str$),
    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Uncoiler 6000 lbs Non-Powered$str$, 1.73, 1.09, 0.95, $str$Uncoiler:Uncoiler 6000 lbs Non-Powered:India$str$),
    ($str$India$str$, $str$IN$str$, $str$sheet_roll_forming_uncoiler$str$, $str$Uncoiler 8000 lbs Powered$str$, 1.73, 3.66, 0.96, $str$Uncoiler:Uncoiler 8000 lbs Powered:India$str$)
  ) AS v(location, country, machine_class, machine_name, labor, direct, indirect, source_key)
  LOOP
    SELECT id INTO src_id FROM mhr_records
    WHERE process_group = $str$Sheet Metal Roll Forming$str$ AND location = 'USA' AND machine_class = r.machine_class AND machine_name = r.machine_name
    LIMIT 1;
    IF src_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.machine_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = r.location AND m.machine_class = r.machine_class AND m.machine_name = r.machine_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records src WHERE src.id = $1', cols, sel)
      USING src_id, r.direct, r.indirect, r.labor, r.location, r.country, r.source_key;
    n := n + 1;
  END LOOP;

  RAISE NOTICE '% twins inserted: %', $str$Sheet Metal Roll Forming$str$, n;
  IF array_length(missing, 1) > 0 THEN
    RAISE NOTICE '% twins with no USA row (not inserted): %', $str$Sheet Metal Roll Forming$str$, missing;
  END IF;
END $roll_forming_machines$;

UPDATE mhr_records m SET specs = m.specs || jsonb_build_object('rate_basis', v.basis), updated_at = now()
FROM (VALUES
  ($str$sheet_roll_forming_coil_flattener$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$),
  ($str$sheet_roll_forming_coil_material_stock$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 0 - Metal India 0.00$str$),
  ($str$sheet_roll_forming_cut_off_press$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$),
  ($str$sheet_roll_forming_integrated_hfi_welding$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$),
  ($str$sheet_roll_forming_integrated_laser_welding$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$),
  ($str$sheet_roll_forming_integrated_rotary_spot_welding$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$),
  ($str$sheet_roll_forming_integrated_tig_welding$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$),
  ($str$sheet_roll_forming_punch_press$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$),
  ($str$sheet_roll_forming_roll_forming_mill$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 4 - Metal India 2.30$str$),
  ($str$sheet_roll_forming_uncoiler$str$, $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$)
) AS v(machine_class, basis)
WHERE m.process_group = $str$Sheet Metal Roll Forming$str$ AND m.location = 'India' AND m.machine_class = v.machine_class AND m.specs IS NOT NULL
  AND m.specs ->> 'rate_basis' IS DISTINCT FROM v.basis;

DO $roll_forming_material_group$
BEGIN
  -- Absent only in a stripped-down database (the local data stub): nothing to link there.
  IF to_regclass('public.process_material_groups') IS NULL THEN RETURN; END IF;
  INSERT INTO public.process_material_groups (process_group, material_group)
  SELECT $str$Sheet Metal Roll Forming$str$, $str$Sheet Metal Roll Forming$str$
   WHERE NOT EXISTS (SELECT 1 FROM public.process_material_groups WHERE process_group = $str$Sheet Metal Roll Forming$str$ AND material_group = $str$Sheet Metal Roll Forming$str$);
  IF NOT EXISTS (SELECT 1 FROM public.raw_materials WHERE material_group = $str$Sheet Metal Roll Forming$str$) THEN
    RAISE EXCEPTION 'Sheet Metal Roll Forming: raw_materials holds none of its materials (migration 855)';
  END IF;
END $roll_forming_material_group$;

DO $roll_forming_check$
DECLARE bad text[]; kept text[]; n integer;
BEGIN
  SELECT count(*) INTO n FROM mhr_records WHERE process_group = $str$Sheet Metal Roll Forming$str$ AND location = 'India' AND machine_class LIKE 'sheet_roll_forming_%';
  IF n <> 125 THEN RAISE EXCEPTION 'expected 125 India Sheet Metal Roll Forming machines, found %', n; END IF;
  SELECT array_agg(location || ': ' || machine_name ORDER BY location, machine_name) INTO bad FROM mhr_records
   WHERE process_group = $str$Sheet Metal Roll Forming$str$ AND location IN ('USA', 'India') AND machine_class LIKE 'sheet_roll_forming_%'
     AND NOT COALESCE(mhr_usd_per_hour, 0) > 0;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Sheet Metal Roll Forming machines without a machine rate: %', bad; END IF;
  SELECT array_agg(location || ': ' || machine_name ORDER BY location, machine_name) INTO bad FROM mhr_records
   WHERE process_group = $str$Sheet Metal Roll Forming$str$ AND location IN ('USA', 'India') AND machine_class LIKE 'sheet_roll_forming_%'
     AND machine_class <> $str$sheet_roll_forming_coil_material_stock$str$ AND NOT COALESCE(usd_labor_rate_per_hr, 0) > 0;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Sheet Metal Roll Forming machines without labour: %', bad; END IF;
  -- A USA row whose rate someone changed after migration 862 keeps it: say which.
  SELECT array_agg(machine_name ORDER BY machine_name) INTO kept FROM mhr_records
   WHERE process_group = $str$Sheet Metal Roll Forming$str$ AND location = 'USA' AND machine_class LIKE 'sheet_roll_forming_%' AND specs ->> 'rate_basis' IS NULL;
  IF kept IS NOT NULL THEN RAISE NOTICE 'Sheet Metal Roll Forming USA machines keeping a rate set in HR Rates: %', kept; END IF;
END $roll_forming_check$;

